$ErrorActionPreference = 'Stop'
# 검토 페이지는 이미지와 자료를 모두 내장해 서버 없이 연다.
$data=@{}
Get-ChildItem $PSScriptRoot -Filter '*.png' | Where-Object {$_.Name -notmatch 'generated|corrected|selected'} | ForEach-Object {$data[$_.BaseName]='data:image/png;base64,'+[Convert]::ToBase64String([IO.File]::ReadAllBytes($_.FullName))}
$images=$data|ConvertTo-Json -Compress
$palettes=Get-Content -Raw -Encoding UTF8 (Join-Path $PSScriptRoot 'palettes.json')
$html=@'
<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>K-064 적 서기 · 6판 방향 검토</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#151a1a;color:#ede9dc;font:15px/1.7 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:32px 24px 80px}h1{font-size:30px;margin-bottom:8px}h2{font-size:22px;margin-top:42px}h3{font-size:18px}p{max-width:1100px;color:#c6c9bc}.tag{color:#d4b974;font-weight:bold}button,select{background:#2b3432;color:#eee5ca;border:1px solid #74775e;padding:9px 16px;margin:4px;cursor:pointer}.scroll{overflow:auto;border:1px solid #4c574d;border-radius:8px;margin:14px 0;background:#252d2b}.lineup{display:flex;align-items:end;gap:16px;width:max-content;padding:14px 20px 0}.unit{margin:0;text-align:center;flex:none}.stage{height:var(--h);position:relative;display:flex;align-items:end;justify-content:center;background:repeating-conic-gradient(#27312d 0 25%,#2c3632 0 50%) 0/16px 16px}.stage:after{content:'';position:absolute;height:1px;background:#d8bf77;bottom:var(--foot);left:0;right:0;pointer-events:none}.stage img{display:block;image-rendering:pixelated;max-width:none}figcaption{font-size:12px;line-height:1.5;min-height:49px;padding:8px 2px;color:#d4d3c1}.comparison .stage{min-width:180px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:18px}.card{padding:18px;background:#202825;border:1px solid #3e4c43;border-radius:8px}.swatch{display:inline-block;width:25px;height:25px;border:1px solid #777;margin:2px;vertical-align:middle}.game{height:720px;position:relative;overflow:auto;background:linear-gradient(#353e37 0 45%,#41452e 45% 100%);border:1px solid #647157;border-radius:8px}.game .actors{position:absolute;bottom:90px;display:flex;align-items:end;gap:25px;padding:0 24px;width:max-content}.game figure{position:relative;margin:0;text-align:center}.game img{display:block;image-rendering:pixelated;margin:auto}.game figcaption{position:absolute;top:100%;left:50%;transform:translateX(-50%);width:130px}.game:after{content:'';position:absolute;left:0;right:0;bottom:90px;height:1px;background:#d8bf77}.game .caption{position:absolute;left:24px;top:20px}.notice{border-left:3px solid #b6a261;padding:10px 18px;background:#252d25}table{border-collapse:collapse;width:100%;font-size:14px}th,td{border-bottom:1px solid #4b574b;padding:9px;text-align:left}a{color:#e0c67f}code{color:#dbcca8}details{margin-top:18px}footer{margin-top:38px;color:#abb3a4}
</style><main>
<div class="tag">Human Last Rampart · 카드 K-064 · 서기 기준안 v1</div><h1>적 3종, 앞·옆 서기 8장</h1>
<p>주인공 6판의 작은 머리·작은 눈, 또렷한 어깨·몸통·다리, 절제된 픽셀 명암을 적용한 검토안입니다. 주인공과 병사는 기존 파일을 비교용으로만 사용했습니다. 고블린의 구부정함과 오우거의 육중한 체격을 구분했습니다.</p>
<div class="notice">사용자 개별 그림 확인 전입니다. 서기 8장만 제작했으며 걷기·공격·사다리 설치·쓰러짐·노멀맵·게임 연결은 이번 결과에 포함되지 않습니다.</div>
<h2>같은 도트 배율 · 같은 발선</h2><p>노란 선은 발 기준입니다. 고블린 56×112 / 중심 x28 / 발 y104, 오우거 112×160 / 중심 x56 / 발 y152. 모든 칸의 아래 여백은 8점입니다. 이 구간은 도트 밀도 비교이며 게임 속 종족 크기 비율은 아래에서 따로 적용합니다.</p>
<button onclick="drawLineup(1)">1배 원본</button><button onclick="drawLineup(4)">최근접 4배</button><span id="zoom"></span><div class="scroll"><div id="lineup" class="lineup"></div></div>
<h2>기존 그림과 전후 비교</h2><p>각 전후의 인물 키를 같게 맞췄습니다. 기존 곤봉 고블린은 걷기 시트 첫 칸이며 기존 사다리병은 사다리 든 정적 그림입니다. 사다리 없는 기존 별도 원화와 기존 측면 서기는 없어 비교를 꾸미지 않았습니다.</p><div id="before" class="cards"></div>
<h2>병사와 실제 코드 비율로 크기 비교</h2><p>병사 키 96점을 기준으로 성벽 앞 비율을 적용하면 고블린 68점, 사다리병 77점, 오우거 110점입니다. 원본 시트 키만으로 크기를 정하지 않고 기본 시트 GUID 연결·개체 크기·성벽 앞 축소·시트 보정을 함께 읽었습니다.</p><div class="scroll"><div class="lineup" id="ratios"></div></div>
<table><thead><tr><th>대상</th><th>기본 시트 / 측정 키</th><th>성벽 앞 보이는 키 계산</th><th>병사 대비</th></tr></thead><tbody><tr><td>인간형 병사</td><td>archer_static / 300</td><td>1.4 × 0.25 × (384/300) × (300/384) = 0.350m</td><td>1.000</td></tr><tr><td>곤봉 고블린</td><td>goblin_walk_attack4 / 240</td><td>1.2 × 0.33 × 240/384 = 0.2475m</td><td>0.707</td></tr><tr><td>사다리 고블린</td><td>ladder_goblin_walk / 272</td><td>1.2 × 0.33 × 272/384 = 0.2805m</td><td>0.801</td></tr><tr><td>오우거</td><td>ogre_walk / 233</td><td>2.0 × 0.33 × 233/384 = 0.40047m</td><td>1.144</td></tr></tbody></table>
<p>들판에서는 축소 계수가 0.33에서 1로 변합니다. 병사는 계속 0.35m이므로 거리별 상대 크기도 변합니다. 오우거 정적 그림의 173점은 현재 기본 걷기 시트의 233점과 달라 크기 계산에 대신 쓰지 않았습니다.</p>
<h2>화면 높이 약 13% · 작은 표시 비교</h2><p>720점 높이 화면에 인간형 병사의 보이는 키를 94점(13.06%)으로 두고 같은 위치의 적 비율을 적용했습니다. 도식 배경이며 실제 Unity 카메라 캡처가 아닙니다. 이전/새 그림을 같은 키와 발선으로 볼 수 있습니다.</p><button onclick="drawGame(false)">새 그림</button><button onclick="drawGame(true)">기존 그림</button><div id="game" class="game"></div>
<h2>기존 시트에서 추출한 실제 색</h2><p>원본 첫 칸의 알파 128 이상 픽셀에서 재질별 목표 명암에 가까운 실제 RGB를 골랐고, 새 그림의 불투명 픽셀을 이 팔레트로 제한했습니다. 임의의 새 RGB를 최종 PNG에 추가하지 않았습니다. 알파는 0/255만 사용합니다.</p><div id="palettes" class="cards"></div>
<details><summary>검토 자료와 남은 확인</summary><p>기준: Docs/References/codex_hero_octopath_review_v6/APPROVED_DIRECTION.md, corrected.png, hero_idle_56x112.png. 크기 근거: PerfLabSheetHeights.cs, PerfLabArt.cs, BattleView.cs, BattleSim.cs, BattleJobs.cs 및 Enemies의 asset→시트 meta GUID.</p><p>모든 측면은 왼쪽을 봅니다. 사다리 운반 그림은 사다리 포함 98점이며 몸 키는 약 95~96점입니다. 사다리 든 모습과 빈손 모습은 같은 정체성으로 생성했지만 세부 옷 주름과 머리카락 점은 완전히 같은 픽셀은 아닙니다. 1점 외곽선과 재질별 3~4단은 제작 방향이며 모든 국소 영역의 단계 수를 수작업 확정한 것은 아닙니다. 축소된 눈·송곳니·손과 사다리 접촉은 사용자 확인이 필요합니다.</p><p>PNG 16개(원본 8 + 4배 8), 팔레트·변환·검사 기록·정확한 생성 프롬프트와 원안을 Docs/References/codex_k064_v1/에 보관했습니다. 최종 PNG의 규격·알파·팔레트·4배 최근접 일치를 검사했습니다. Unity는 실행하지 않았습니다.</p></details><footer>2026-10-19 · 내장 이미지 생성 도구 제작 / 기술 정규화 · Game 수정 없음 · 게임 연결 Claude 담당(D-074)</footer>
</main><script>
const images=__IMAGES__, palettes=__PALETTES__;
const units=[['hero_v6_reference','주인공 6판 · 기존 참조',56,112,96],['soldier_reference','인간형 병사 · 기존 참조',112,112,96],['goblin_front','고블린 · 앞',56,112,96],['goblin_side','고블린 · 옆',56,112,96],['ladder_empty_front','사다리병 빈손 · 앞',56,112,96],['ladder_empty_side','사다리병 빈손 · 옆',56,112,96],['ladder_carry_front','사다리병 운반 · 앞',56,112,98],['ladder_carry_side','사다리병 운반 · 옆',56,112,98],['ogre_front','오우거 · 앞',112,160,128],['ogre_side','오우거 · 옆',112,160,128]];
function figure(u,z){return `<figure class="unit"><div class="stage" style="--h:${160*z}px;--foot:${8*z}px"><img alt="${u[1]}" src="${images[u[0]]}" width="${u[2]*z}" height="${u[3]*z}"></div><figcaption>${u[1]}<br>${u[2]}×${u[3]}</figcaption></figure>`}
function drawLineup(z){document.querySelector('#lineup').innerHTML=units.map(u=>figure(u,z)).join('');document.querySelector('#zoom').textContent=z+'배 · 도트 배율 동일'}
for(const [id,label] of [['goblin','곤봉 고블린'],['ladder_empty','사다리 고블린 · 빈손'],['ladder_carry','사다리 고블린 · 운반'],['ogre','오우거']]){let u=units.find(u=>u[0]===id+'_front');document.querySelector('#before').innerHTML+=`<article class="card"><h3>${label}</h3><div class="scroll"><div class="lineup comparison">${figure([id+'_before','기존'+(id==='ladder_empty'?' · 운반 원화':''),160,u[3],u[4]],2)}${figure([id+'_front','새 앞모습',u[2],u[3],u[4]],2)}${figure([id+'_side','새 옆모습',u[2],u[3],u[4]],2)}</div></div></article>`}
const ratioUnits=[['soldier_reference','인간형 병사',96,112,112],['goblin_front','고블린',96*0.707142857,56,112],['ladder_empty_front','사다리병 · 빈손',96*0.801428571,56,112],['ladder_carry_front','사다리병 · 운반',96*0.801428571*98/95,56,112],['ogre_front','오우거',96*1.144196429,112,160]];
function scaled(u,target){const native=u[0].startsWith('ogre')?128:(u[0].startsWith('ladder_carry')?98:96);return u[2]/native*target}
document.querySelector('#ratios').innerHTML=ratioUnits.map(u=>{let scale=scaled(u,1);return `<figure class="unit"><div class="stage" style="--h:160px;--foot:0px"><img alt="${u[1]}" src="${images[u[0]]}" style="width:${u[3]*scale}px;height:${u[4]*scale}px;margin-bottom:${-8*scale}px"></div><figcaption>${u[1]} · 약${Math.round(u[2])}점</figcaption></figure>`}).join('');
function drawGame(old){document.querySelector('#game').innerHTML=`<div class="caption">${old?'기존 그림':'새 서기 기준'} · 720점 화면 / 병사94점<br>같은 거리 · 성벽 앞 계수0.33 · 도식 비교</div><div class="actors">`+ratioUnits.map(u=>{let key=old?u[0].replace(/_(front)$/,'_before'):u[0];if(key==='ladder_empty_before')key='ladder_carry_before';let native=u[0].startsWith('ogre')?128:(u[0].startsWith('ladder_carry')?98:96);let scale=u[2]/native*94/96;let width=old&&u[0]!=='soldier_reference'?160:u[3];return `<figure><img alt="${u[1]}" src="${images[key]}" style="width:${width*scale}px;height:${u[4]*scale}px;margin-bottom:${-8*scale}px"><figcaption>${u[1]}</figcaption></figure>`}).join('')+'</div>'}
for(const id of ['goblin','ladder_empty','ogre']){let p=palettes[id];document.querySelector('#palettes').innerHTML+=`<article class="card"><h3>${id==='goblin'?'곤봉 고블린':id==='ogre'?'오우거':'사다리 고블린 · 두 상태 공통'}</h3><p style="overflow-wrap:anywhere">${p.source}</p>${p.colors.map(c=>`<span class="swatch" style="background:${c}" title="${c}"></span>`).join('')}<p>${p.colors.join(' · ')}</p></article>`}
drawLineup(1);drawGame(false);
</script></html>
'@
$html=$html.Replace('__IMAGES__',$images).Replace('__PALETTES__',$palettes)
$root=(Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
$out=Join-Path $root '_HTML/4_그림_캐릭터/codex_K-064_적6판방향_v1.html'
New-Item -ItemType Directory -Force (Split-Path $out)|Out-Null
[IO.File]::WriteAllText($out,$html,(New-Object Text.UTF8Encoding($false)))
Write-Output $out
